import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './flex.module.css'
import type { SpaceStep } from '@cascivo/core'

export interface FlexProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Flex direction. ⚠ Defaults to `vertical`, unlike CSS `flex-direction` (and unlike
   * Chakra/MUI/Radix `Flex`, which default to a row) — `<Flex justify="between">` alone
   * produces a centered vertical stack.
   *
   * @defaultValue `vertical`
   * @see the component manifest
   */
  direction?: 'vertical' | 'horizontal'
  /**
   * Spacing token step
   *
   * @defaultValue `4`
   * @see the component manifest
   */
  gap?: SpaceStep
  align?: 'start' | 'center' | 'end' | 'stretch'
  justify?: 'start' | 'center' | 'end' | 'between'
  /**
   * Allow wrapping
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  wrap?: boolean
}

export function Flex({
  direction = 'vertical',
  gap = 4,
  align,
  justify,
  wrap = false,
  className,
  style,
  ...props
}: FlexProps) {
  return (
    <div
      className={cn(styles['flex'], className)}
      data-direction={direction}
      data-wrap={wrap ? '' : undefined}
      style={{
        ['--_flex-gap' as string]: `var(--cascivo-space-${gap})`,
        ...(align
          ? { alignItems: align === 'start' || align === 'end' ? `flex-${align}` : align }
          : {}),
        ...(justify
          ? {
              justifyContent:
                justify === 'between'
                  ? 'space-between'
                  : justify === 'start' || justify === 'end'
                    ? `flex-${justify}`
                    : justify,
            }
          : {}),
        ...style,
      }}
      {...props}
    />
  )
}

@layer cascivo.component {
  .flex {
    display: flex;
    gap: var(--_flex-gap, var(--cascivo-space-4));

    &[data-direction='vertical'] {
      flex-direction: column;
    }
    &[data-direction='horizontal'] {
      flex-direction: row;
    }
    &[data-wrap] {
      flex-wrap: wrap;
    }
  }
}
